import{_ as a,c as t,o,ag as i}from"./chunks/framework.ARG558ZT.js";const m=JSON.parse('{"title":"A12 — Q Developer and AWS AI integrations","description":"","frontmatter":{},"headers":[],"relativePath":"practice/aws/associate-12.md","filePath":"practice/aws/associate-12.md"}'),n={name:"practice/aws/associate-12.md"};function r(s,e,l,d,c,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="a12-—-q-developer-and-aws-ai-integrations" tabindex="-1">A12 — Q Developer and AWS AI integrations <a class="header-anchor" href="#a12-—-q-developer-and-aws-ai-integrations" aria-label="Permalink to “A12 — Q Developer and AWS AI integrations”">​</a></h1><p><strong>Learner status: not started. All supplied tasks are mandatory here</strong>, including every originally optional exploration and the bonus pipeline. This is the AI lab called “Lab 11” in the source; A11 here denotes CI/CD.</p><p><strong>Read first:</strong> <a href="./../../aws/ai-services.html">AWS AI services</a>, <a href="./../../aws/serverless-and-apis.html">serverless APIs</a>, and <a href="./source-notes.html">source corrections</a>. <a href="/aws-homework/sources/associate-12.txt">Original supplied text</a> retains the original instructions and examples.</p><p><strong>Repeating:</strong> Lambda, API Gateway, IAM, SDK packaging and tests repeat P03/A10/A11. The new evidence is the AI service behavior, review of generated code and multi-service integration. Use a supported Node.js runtime and deliberate ESM/build configuration; do not copy the source&#39;s Node.js 18 deployment unchanged.</p><h2 id="a12-1-—-set-up-amazon-q-developer" tabindex="-1">A12.1 — Set up Amazon Q Developer <a class="header-anchor" href="#a12-1-—-set-up-amazon-q-developer" aria-label="Permalink to “A12.1 — Set up Amazon Q Developer”">​</a></h2><ul><li>[ ] Install Q Developer in one selected supported IDE: VS Code or JetBrains. Authenticate through the source&#39;s supported Builder ID or Identity Center option.</li><li>[ ] Verify chat responds to a Lambda question and code suggestions work. Record installation/authentication evidence without exposing credentials.</li></ul><h2 id="a12-2-—-build-and-deploy-a-sentiment-analysis-api" tabindex="-1">A12.2 — Build and deploy a sentiment-analysis API <a class="header-anchor" href="#a12-2-—-build-and-deploy-a-sentiment-analysis-api" aria-label="Permalink to “A12.2 — Build and deploy a sentiment-analysis API”">​</a></h2><p>The required architecture is <strong>API Gateway → Lambda → Amazon Comprehend → HTTP response</strong>. Direct Lambda invocation is additional evidence, not a replacement for the HTTP integration omitted from the source&#39;s deployment snippet.</p><ul><li>[ ] Initialize a Node.js project and install SDK v3&#39;s <code>@aws-sdk/client-comprehend</code> and required development types.</li><li>[ ] Use Q to draft a Lambda handler, then review and understand it. Parse the chosen API Gateway event, call <code>DetectSentiment</code>, and return the sentiment classification and confidence scores in the correct HTTP integration response format.</li><li>[ ] Add malformed-input and service-error handling. Implement the source&#39;s requested batch-analysis support with the appropriate API contract; verify both individual and batch paths.</li><li>[ ] Validate non-empty text, supported language and the selected service operation&#39;s UTF-8 <strong>byte</strong> limit. The source&#39;s “1–5000 characters” rule is not a correct substitute for the 5 KB single-document API limit.</li><li>[ ] Create local tests for positive, negative and neutral examples, invalid/oversized input and failure handling. Explain any nondeterministic service output instead of asserting invented exact confidence values.</li><li>[ ] Give the function scoped Comprehend access and log permissions. Package the code, dependencies and required module metadata; deploy it to AWS.</li><li>[ ] Create and configure the HTTP API integration, permissions, route and CORS if the selected client needs it. Test the deployed HTTP endpoint and the source&#39;s direct-invocation path, accounting for their different event shapes.</li><li>[ ] Confirm the deployed function actually calls Comprehend and returns an appropriate response. Retain local and remote results.</li></ul><h2 id="a12-3-—-review-generated-code-and-use-q-features" tabindex="-1">A12.3 — Review generated code and use Q features <a class="header-anchor" href="#a12-3-—-review-generated-code-and-use-q-features" aria-label="Permalink to “A12.3 — Review generated code and use Q features”">​</a></h2><ul><li>[ ] Request a code explanation and check it against the implementation.</li><li>[ ] Run the available supported security-scanning workflow, inspect findings, review proposed fixes and record unresolved limitations. If the old IDE menu is unavailable, document the supported equivalent used.</li><li>[ ] Generate unit tests, inspect their assertions, run them and record coverage without treating generated tests as inherently sufficient.</li><li>[ ] Request performance suggestions, implement one justified optimization and explain its effect. Avoid claiming an improvement without evidence.</li><li>[ ] Generate and review JSDoc and project documentation.</li></ul><h2 id="a12-4-—-rekognition-exploration-—-promoted-from-optional" tabindex="-1">A12.4 — Rekognition exploration — promoted from optional <a class="header-anchor" href="#a12-4-—-rekognition-exploration-—-promoted-from-optional" aria-label="Permalink to “A12.4 — Rekognition exploration — promoted from optional”">​</a></h2><ul><li>[ ] Use synthetic or provided sample images to investigate label detection, text detection, face detection and face comparison in the available console workflows.</li><li>[ ] Record confidence scores, bounding boxes and multiple-object behavior. Explain an intended threshold, its tradeoff and a relevant application use case; do not treat confidence as proof of correctness.</li></ul><h2 id="a12-5-—-polly-exploration-—-promoted-from-optional" tabindex="-1">A12.5 — Polly exploration — promoted from optional <a class="header-anchor" href="#a12-5-—-polly-exploration-—-promoted-from-optional" aria-label="Permalink to “A12.5 — Polly exploration — promoted from optional”">​</a></h2><ul><li>[ ] Convert the source&#39;s welcome text to speech; compare available neural/standard voices and languages.</li><li>[ ] Experiment with SSML pauses, emphasis and rate; download the generated audio and inspect speech marks for a synchronization use case.</li><li>[ ] Explain the selected voice, integration approach and cost implications for higher usage. Feature support varies by voice/engine; record the actual supported choices.</li></ul><h2 id="a12-6-—-translate-exploration-—-promoted-from-optional" tabindex="-1">A12.6 — Translate exploration — promoted from optional <a class="header-anchor" href="#a12-6-—-translate-exploration-—-promoted-from-optional" aria-label="Permalink to “A12.6 — Translate exploration — promoted from optional”">​</a></h2><ul><li>[ ] Translate the source&#39;s technical paragraph from English into Spanish, French, German and Japanese; compare results.</li><li>[ ] Test automatic source-language detection and domain terminology.</li><li>[ ] Create/apply custom terminology, including preservation of a term such as Lambda where supported. Compare results with and without it.</li><li>[ ] Explain unsupported-language handling and when custom terminology helps.</li></ul><h2 id="a12-7-—-textract-exploration-—-promoted-from-optional" tabindex="-1">A12.7 — Textract exploration — promoted from optional <a class="header-anchor" href="#a12-7-—-textract-exploration-—-promoted-from-optional" aria-label="Permalink to “A12.7 — Textract exploration — promoted from optional”">​</a></h2><ul><li>[ ] Analyze synthetic invoice/receipt, form and table samples with suitable text/form/table operations.</li><li>[ ] Inspect extracted text, key-value pairs, table structure and confidence scores. Export the JSON and relate its structure to programmatic processing.</li><li>[ ] Explain handling of low-confidence extraction, useful post-processing and integration into a workflow.</li></ul><h2 id="a12-8-—-bedrock-exploration-and-comparison-—-promoted-from-optional" tabindex="-1">A12.8 — Bedrock exploration and comparison — promoted from optional <a class="header-anchor" href="#a12-8-—-bedrock-exploration-and-comparison-—-promoted-from-optional" aria-label="Permalink to “A12.8 — Bedrock exploration and comparison — promoted from optional”">​</a></h2><ul><li>[ ] Select currently accessible foundation models and satisfy their current access prerequisites. Compare two available models; if a named historical model is unavailable, record the actual substitute for this exploration.</li><li>[ ] Test code generation, summarization and JSON-to-SQL transformation prompts, plus one personal application use case with synthetic input.</li><li>[ ] Vary temperature/top-p/max-token parameters where the selected model supports them. Record unsupported combinations instead of assuming identical APIs for all models.</li><li>[ ] Produce a comparison table of outputs, parameter effects, suitability and cost considerations. Review generated SQL/code before any execution.</li></ul><h2 id="a12-9-—-combined-ai-pipeline-—-promoted-from-bonus" tabindex="-1">A12.9 — Combined AI pipeline — promoted from bonus <a class="header-anchor" href="#a12-9-—-combined-ai-pipeline-—-promoted-from-bonus" aria-label="Permalink to “A12.9 — Combined AI pipeline — promoted from bonus”">​</a></h2><ul><li>[ ] Build the required document flow: <strong>uploaded image → Textract → Translate to English if needed → Comprehend sentiment → Bedrock summary</strong>.</li><li>[ ] Use Q to assist architecture work, then choose Step Functions or a Lambda orchestrator and implement each integration with the necessary scoped permissions.</li><li>[ ] Test synthetic documents in different languages, inspect intermediate outputs and measure end-to-end latency. Explain what happens when an intermediate service fails rather than silently inventing a final result.</li></ul><h2 id="a12-10-—-all-deliverables-and-cleanup" tabindex="-1">A12.10 — All deliverables and cleanup <a class="header-anchor" href="#a12-10-—-all-deliverables-and-cleanup" aria-label="Permalink to “A12.10 — All deliverables and cleanup”">​</a></h2><ul><li>[ ] Retain IDE setup evidence; complete implementation, validation, error handling, tests, reviewed documentation and the optimization explanation.</li><li>[ ] Retain local/deployed results, security-scan results, service-exploration observations, Bedrock comparison, combined-pipeline code/results and reflection notes.</li><li>[ ] Follow repository/submission rules: only the user may push. Source wording “all or some” deliverables is replaced by <strong>all listed deliverables</strong> in this path.</li><li>[ ] Remove unused API/function/workflow/log/storage resources and record any remaining chargeable resources. Do not leave uploaded document data or generated artifacts without an explicit retention decision.</li></ul><p>The source&#39;s generic “Next Steps” links are further reading, not additional unbounded deliverables. Use the <a href="./#evidence-for-every-required-module">shared evidence rules</a>. Additional AI evaluation beyond these supplied tasks remains <a href="./optional-extensions.html#x12-ai-quality-and-failure-evaluation">optional X12</a>.</p>',26)])])}const h=a(n,[["render",r]]);export{m as __pageData,h as default};
